+                }
+            }
+        }
+
+        IndexRouting routing(Index index) {
+            IndexRouting routing = routings.get(index);
+            if (routing == null) {
+                routing = IndexRouting.fromIndexMetadata(state.metadata().getIndexSafe(index));
+                routings.put(index, routing);
+            }
+            return routing;
+        }
+    }
