+                    var entryAsString = entry.getKey() + "=" + entry.getValue();
+                    if (node == entry) {
+                        return "<<" + entryAsString + ">>";
+                    }
+                    return entryAsString;
+                }).collect(Collectors.joining(", ", "{", "}"));
